import os,stat,hashlib,json
root=os.path.realpath(os.getcwd()); entries={}
def visit(base):
 for e in sorted(os.scandir(base),key=lambda x:x.name):
  p=e.path; rel=os.path.relpath(p,root); s=os.lstat(p)
  if e.name=='.git': continue
  state={'mode':str(s.st_mode),'size':str(s.st_size),'mtime_ns':str(s.st_mtime_ns),'ctime_ns':str(s.st_ctime_ns),'ino':str(s.st_ino),'dev':str(s.st_dev)}
  if stat.S_ISLNK(s.st_mode): state['link']=os.readlink(p)
  elif stat.S_ISDIR(s.st_mode):
   if os.path.lexists(os.path.join(p,'.git')): state['boundary']='nested repository'
   else: visit(p)
  elif stat.S_ISREG(s.st_mode) and rel not in ['.env','local.db','certificate.crt','.npmrc']:
   state['sha256']=hashlib.sha256(open(p,'rb').read()).hexdigest()
  entries[rel]=state
visit(root)
print(json.dumps({'root':root,'entries':entries}))
